from os import popen


def get_vm_ip_address(ifname):
    """
    Return the IP address as string of UTE VM on given interface.

    :param ifname: interface name
    :type ifname: str
    :return: IP address
    :rtype: str
    """
    ipaddr_cmd = popen(f"ip addr show {ifname} " + r"| grep -e 'inet\s' | awk '{print $2}' | cut -d/ -f1")
    ip_addr = ipaddr_cmd.read()
    return ip_addr.strip()


def get_vm_user():
    """
    Return the actual user name of UTE VM

    :return: user name
    :rtype: str
    """
    whoami_cmd = popen('/usr/bin/whoami')
    username = whoami_cmd.read()
    return username.strip()


def get_vm_password():
    """
    Return the access password of UTE VM

    :return: password
    :rtype: str
    """
    # assert password is the same as username
    return get_vm_user()


def get_vm_test_logs_dir():
    """
    Return path to the log directory of current test.
    :return: password
    :rtype: str
    """
    from ute_common_abstract_core import logger as core_logger
    return core_logger.logging_path


def get_vm_ssh_port():
    """
    Return the port of ssh service of UTE VM
    :return: port
    :rtype: int
    """
    return 22
